+
+<script>
+  let currentFormats = {};
+
+  document.getElementById('generate-btn').addEventListener('click', async () => {
+    const repo = document.getElementById('repo').value.trim();
+    const since = document.getElementById('since').value;
+    const until = document.getElementById('until').value || null;
+    const btn = document.getElementById('generate-btn');
+    const status = document.getElementById('status');
+
+    if (!repo) { status.textContent = 'Please enter a repository path or URL.'; status.className = 'error'; return; }
+
+    btn.disabled = true;
+    btn.textContent = 'Generating…';
+    status.textContent = 'Extracting commits and analysing diffs…';
+    status.className = '';
+    document.getElementById('results').classList.add('hidden');
+
+    try {
+      const res = await fetch('/api/generate', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ repo, since, until }),
+      });
+
+      const data = await res.json();
+      if (!res.ok) { throw new Error(data.detail || 'Unknown error'); }
+
+      currentFormats = data.formats;
+
+      // Before / After
+      document.getElementById('raw-log').textContent = data.summary.raw_log.join('\n');
+      document.getElementById('summary-preview').textContent = data.formats.slack;
+
+      // Blockers
+      const blockersSection = document.getElementById('blockers-section');
+      const blockersList = document.getElementById('blockers-list');
+      blockersList.innerHTML = '';
+      if (data.summary.blockers.length > 0) {
+        blockersSection.classList.remove('hidden');
+        data.summary.blockers.forEach(b => {
+          const li = document.createElement('li');
+          if (b.reason === 'repeated_changes') {
+            li.textContent = `${b.target} was modified in 3+ commits — possible rework or ongoing issue.`;
+          } else {
+            li.textContent = `Commit ${b.target.slice(0,7)} flagged: "${b.message}" — possible struggle.`;
+          }
+          blockersList.appendChild(li);
+        });
+      } else {
+        blockersSection.classList.add('hidden');
+      }
+
+      // Outputs
+      document.getElementById('output-slack').textContent = data.formats.slack;
+      document.getElementById('output-email').textContent = data.formats.email;
+      document.getElementById('output-standup').textContent = data.formats.standup;
+
+      document.getElementById('results').classList.remove('hidden');
+      status.textContent = `Done — ${data.summary.raw_log.length} commit(s) analysed.`;
+
+    } catch (err) {
+      status.textContent = `Error: ${err.message}`;
+      status.className = 'error';
+    } finally {
+      btn.disabled = false;
+      btn.textContent = 'Generate';
+    }
+  });
+
+  // Tab switching
+  document.querySelectorAll('.tab-btn').forEach(btn => {
+    btn.addEventListener('click', () => {
+      document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
+      document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
+      btn.classList.add('active');
+      document.getElementById('tab-' + btn.dataset.tab).classList.add('active');
+    });
+  });
+
+  function copyTab(format) {
+    navigator.clipboard.writeText(currentFormats[format] || '').then(() => {
+      const btn = event.target;
+      btn.textContent = 'Copied!';
+      setTimeout(() => btn.textContent = 'Copy', 1500);
+    });
+  }
+</script>
+</body>
+</html>
